targets = {e['target'] for e in ex}
joiner = ';'
parts = set()
for t in targets:
    for p in t.split(joiner):
        p = p.strip()
        if p: parts.add(p)
vocab = targets | parts
print('LawBench: targets=%d parts=%d vocab=%d' % (len(targets), len(parts), len(vocab)))

cat = Counter()
unlisted_entries = []
for r in rows:
    if r['status'] != 'ok':
        cat['error'] += 1
        continue
    pred, gold = parse_law(r['prediction']), parse_law(r['target'])
    if pred == gold:
        cat['correct'] += 1
        for p in pred:
            if p not in vocab: unlisted_entries.append((r['file'], p, 'CORRECT'))
        continue
    if pred < gold: cat['pure-subset(missing)'] += 1
    elif gold < pred: cat['pure-superset(extra)'] += 1
    elif pred & gold: cat['overlap(both)'] += 1
    else: cat['disjoint'] += 1
    for p in pred:
        if p not in vocab: unlisted_entries.append((r['file'], p, 'WRONG'))
print(cat)
print('\nunlisted predicted entries:', len(unlisted_entries))
for f,p,k in unlisted_entries: print(' ', k, p, '<-', f)
