import sys, json, re
sys.path.insert(0, '/workspace/harness/solver')
from load import RUN
from pathlib import Path

SEPS = (";", "；", ",", "，", "、")
MARKUP = re.compile(r"\[[^\]]*\]|<[^>]*>")

def bare(s): return "".join(c for c in s if c.isalnum())

def ans_text(text):
    text = (text or "").strip()
    m = re.search(r"\[罪名\](.*?)(?:<eoa>|$)", text)
    if m: text = m.group(1).strip()
    elif "罪名:" in text: text = text.split("罪名:")[-1]
    return re.sub(r"<eoa>.*", "", text).strip()

def frags(text):
    text = ans_text(text)
    out = []
    for chunk in re.split(r"[;；,，、]", text):
        chunk = chunk.strip()
        if chunk: out.append(chunk)
    return out

def fragment_vocab(examples):
    """every piece the memory's own answers are written from, split the way a reader splits them"""
    vocab = set()
    for e in examples:
        t = e.get("target")
        if not t: continue
        vocab.add(t.strip())
        for chunk in re.split(r"[;；,，、]", t):
            chunk = chunk.strip()
            if chunk: vocab.add(chunk)
    return vocab

def load_mem(task):
    return json.loads((RUN/task/'memory.json').read_text())["examples"]

def gold_set(target):
    return set(frags(target))

def apply_snap(pred, vocab, max_extra=3, mode="prefix"):
    out = []
    for f in frags(pred):
        b = bare(f)
        if b in {bare(v) for v in vocab} and any(bare(v)==b for v in vocab):
            out.append(next(v for v in vocab if bare(v)==b)); continue
        best = None
        for v in vocab:
            bv = bare(v)
            if not bv or bv == b: continue
            if bv.startswith(b) or b.startswith(bv):
                extra = abs(len(b) - len(bv))
                if extra <= max_extra and (best is None or extra < best[0]):
                    best = (extra, v)
        out.append(best[1] if best else f)
    return ";".join(out)

def evaluate(pred_frag_set, gold_frag_set):
    return pred_frag_set == gold_frag_set

runs = sorted([p.name for p in Path("/workspace/runs").iterdir() if p.is_dir() and (p/"LawBench").is_dir()])
print("runs:", len(runs))
import collections
agg = collections.Counter()
detail = collections.defaultdict(lambda: collections.Counter())
for run in runs:
    global RUN
    RUN = Path("/workspace/runs")/run
    ex = load_mem('LawBench')
    vocab = fragment_vocab(ex)
    bares = {}
    for v in vocab: bares.setdefault(bare(v), v)
    rows = []
    for conv in sorted((RUN/'LawBench'/'conversations').iterdir()):
        if not conv.is_dir() or conv.name=='prepare': continue
        for f in sorted(conv.glob('sample-*.json')):
            rows.append(json.loads(f.read_text()))
    for r in rows:
        if r.get('status') != 'ok': continue
        gold = gold_set(r['target'])
        base_pred = set(frags(r['prediction']))
        base_ok = base_pred == gold
        snap_pred = set(frags(apply_snap(r['prediction'], vocab)))
        snap_ok = snap_pred == gold
        agg['base_correct'] += base_ok
        agg['n'] += 1
        if not base_ok and snap_ok: agg['fix'] += 1; detail[run]['fix'] += 1
        if base_ok and not snap_ok: agg['break'] += 1; detail[run]['break'] += 1
        if not base_ok and snap_ok is False and snap_pred != base_pred: agg['changed_wrong'] += 1
        if base_ok and snap_pred == base_pred: pass
print(dict(agg))
for run in runs: print(run, dict(detail[run]))
