        if characters:
            endings.add(characters[-1])
    return endings


def written_the_lists_way(name: str, listed: set[str], endings: set[str]) -> str:
    """The name with the characters the list never ends one of its names with left off.

    The list is the authority on how its entries are written, and each of its names ends with
    one of the characters its own answers end with. A name the list does not carry that ends
    with a character no listed name ends with is therefore the entry with something appended
    to it -- a title or category word the list never uses -- so the harness writes it the way
    the list writes its names, and stops as soon as it has one. Nothing else is touched: the
    characters come off the end, and the entry is neither exchanged for another nor dropped.
    """
    if name in listed or len(name) < 3:
        return name
    end = len(name)
    while end - 1 >= 2 and name[end - 1] not in endings:
        end -= 1
        if name[:end] in listed:
            break
    return name[:end]


