def piece_of_a_listed_name(name: str, listed: set[str]) -> bool:
    """True when the list writes this string inside one of its own names.

    The list's answers are written from strings like this one -- the key lists those strings
    too, and the skill tells the solver to write one of them on its own when that is all that
    applies -- so a name the list does not carry as an answer can still be a name the list
    writes, and one of those is left exactly as the answer wrote it.
    """
    return any(name != other and name in other for other in listed)


def written_the_lists_way(name: str, listed: set[str], endings: set[str], dividers: str) -> str:
    """The name with the characters the list never ends one of its names with left off.

    The list is the authority on how its entries are written, and each of its names ends with
    one of the characters its own answers end with. A name the list does not carry that ends
    with a character no listed name ends with is therefore the entry with something appended
    to it -- a title or category word the list never uses -- so the harness writes it the way
    the list writes its names, and stops as soon as it has one. Nothing else is touched: the
    characters come off the end, and the entry is neither exchanged for another nor dropped.
    Two names are left alone: one the list writes inside a name of its own, and one the answer
    wrote with a divider inside it, which is several of the list's names and not a name of its
    own -- the readings that a name the list cannot write would otherwise be lost to.
    """
    if name in listed or len(name) < 3 or piece_of_a_listed_name(name, listed):
        return name
