git notes --ref=refs/notes/evolution list | grep 856cc92; echo "---- errors count across the 8 lineage runs ----"; python3 -c "
import json
from pathlib import Path
tot={}
for run in sorted(p for p in Path('/workspace/runs').iterdir() if p.is_dir() and (p/'LawBench').is_dir()):
    for task in ['LawBench','Symptom2Disease','USPTO']:
        conv=run/task/'conversations'
        if not conv.is_dir(): continue
        for c in conv.iterdir():
            if not c.is_dir() or c.name=='prepare': continue
            for f in c.glob('sample-*.json'):
                d=json.loads(f.read_text())
                if d['status']=='error':
                    tot[(task,d['error']['type'])]=tot.get((task,d['error']['type']),0)+1
print(tot)
"; echo "---- final state ----"; git status --short; git log --oneline --graph --decorate -3 --all | head -5
